            this.gestioneClasse.setView(view);
        }
        this.gestioneClasse.start();
        mostraSchermata(this.gestioneClasse.getView());
    }

    @Override
    protected void visualizzaElencoStudenti() {
        System.out.println("[Elenco Studenti GUI — da implementare]");
    }

    // ── Logout ────────────────────────────────────────────────────────────────

    @Override
    public void logout() {
        // Ripulisce la lista stock indipendentemente da qual è la schermata corrente
        impostaListaStock(new ArrayList<>());

        // Resetta il controller ManageWallets prima di liberarlo
        if (this.manageWallets != null) {
            this.manageWallets.reset();
        }

        // Libera tutti i controller
        this.login          = null;
        this.homeStudente   = null;
        this.homeProfessore = null;
        this.manageWallets  = null;
        this.gestioneClasse = null;
    }
